pub fn symbol_at_byte<'a>(syms: &[&'a SymbolRow], byte: i64) -> Option<&'a SymbolRow> {
    syms.iter()
        .copied()
        .filter(|s| {
            s.start_byte
                .zip(s.end_byte)
                .is_some_and(|(start, end)| start <= byte && byte < end)
        })
        .min_by_key(|s| s.end_byte.unwrap() - s.start_byte.unwrap())
}

