fn bound_output(value: &mut Value, budget: usize) -> Result<()> {
    while serde_json::to_vec(&json!({"structuredContent":value,"content":[{"type":"text","text":value.to_string()}],"isError":false}))?.len() > budget {
        let mut removed = false;
        if let Some(data) = value.get_mut("data") {
            if let Some(items) = data.as_array_mut() { removed = items.pop().is_some(); }
            else if let Some(object) = data.as_object_mut() {
                let key = object.iter().filter_map(|(k,v)| v.as_array().filter(|a| !a.is_empty()).map(|a| (k.clone(),a.len()))).max_by_key(|(_,len)| *len).map(|(k,_)| k);
                if let Some(key) = key {
                    let item = object[&key].as_array_mut().unwrap().pop(); removed = item.is_some();
                    if key == "nodes" {
                        let id = item.as_ref().and_then(|i| i.get("id")).cloned();
                        if let Some(edges) = object.get_mut("edges").and_then(Value::as_array_mut) { edges.retain(|e| Some(&e["source"]) != id.as_ref() && Some(&e["target"]) != id.as_ref()); }
                    }
                } else if object.get("content").and_then(Value::as_str).is_some_and(|s| !s.is_empty()) {
                    object.insert("content".into(), json!("")); removed = true;
                }
            }
        }
        anyhow::ensure!(removed, "response metadata exceeds max_output_kb; increase the budget");
        value["metadata"]["truncated"] = json!(true);
        let count = value["metadata"]["omitted_count"].as_u64().unwrap_or(0)+1;
        value["metadata"]["omitted_count"] = json!(count);
    }
    Ok(())
}

