            let is_last = i + 1 == total;
            let branch = if is_last { "└── " } else { "├── " };
            let next_prefix = if is_last { "    " } else { "│   " };

            output.push_str(prefix);
            output.push_str(branch);
            output.push_str(name);
            output.push('\n');

            node.render(output, &format!("{prefix}{next_prefix}"));
        }
    }

